'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data={regattas:[],active:null,settings:{lang:'sk-SK',voice:true,sound:true,count:10,countdownMinutes:5,sun:false}},reg=null,view='home',editing=null,wake=null,audio=null,lastSecond=null,anchorWall=Date.now(),anchorMono=performance.now();
const now=()=>anchorWall+performance.now()-anchorMono;
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').style.display='none',3500)}
function persist(){try{localStorage.setItem('RegattaStopwatchV2',JSON.stringify(data));return true}catch(e){toast('Uloženie zlyhalo. Exportujte zálohu JSON.');return false}}
function button(text,id,cls=''){return `<button class="${cls}" data-action="${id}">${text}</button>`}
function load(){try{const saved=JSON.parse(localStorage.getItem('RegattaStopwatchV2'));if(saved)data={...data,...saved,settings:{...data.settings,...saved.settings}}}catch(e){toast('Uložené dáta sa nepodarilo načítať.')}document.body.classList.toggle('sun',data.settings.sun);if(data.active){reg=data.regattas.find(x=>x.id===data.active.regattaId);if(reg){view=data.active.state==='EVALUATION'?'evaluation':'timer';toast('Rozbehnutá etapa obnovená. Zvuk aktivujete dotykom.')}}render()}
function home(){return `<div class="eyebrow">ROZHODCOVSKÝ PULT</div><div class="row"><div><h1>Moje regaty</h1><p>Od prvého signálu až po posledný dojazd.</p></div>${button('+ Nová regata','new','primary')}</div>${data.active?`<div class="card row"><div><b>Rozbehnutá etapa</b><p>${esc(data.regattas.find(r=>r.id===data.active.regattaId)?.name)}</p></div>${button('Pokračovať','restore','success')}</div>`:''}<div class="card">${data.regattas.length?data.regattas.map(r=>`<div class="item row"><div class="regatta-list-title">${logoMarkup(r,"regatta-list-logo")}<div><b>${esc(r.name)}</b><p>${esc(r.location||'Miesto nezadané')} · ${esc(r.boatClass||'Open')} · ${r.crews.length} lodí</p></div></div>${button('Otvoriť →','open:'+r.id)}</div>`).join(''):`<div class="empty"><h2>Pripravte svoju prvú regatu</h2><p>Pridajte lode, spustite štart a zaznamenajte dojazdy.</p>${button('Vytvoriť regatu','new','primary')}</div>`}</div><div class="actions">${button('Importovať zálohu JSON','import')}${button('Vyskúšať ukážkovú regatu','demo')}</div>`}
function timeTable(){const rows=timeStandings(reg);return `<div class="scroll"><table><thead><tr><th>Por.</th><th>Loď / skipper</th>${reg.races.map((_,i)=>`<th>E${i+1}</th>`).join('')}<th>Celkový čas</th><th title="Rozdiel celkového času oproti predchádzajúcej lodi v poradí">Na predchádzajúcu loď</th><th title="Rozdiel celkového času oproti vedúcej lodi">Na vedúcu loď</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${x.rank?x.rank+'.':'—'}</td><td><b>${esc(x.crew.boatName)}</b><div class="muted">${esc(x.crew.skipper)}</div></td>${x.results.map(r=>{const e=effectiveMs(r);const pen=r.penaltyPct?`<div class="muted">+${r.penaltyPct} % · čistý ${r.status==='OK'&&Number.isFinite(r.ms)?fmt(r.ms):esc(r.status)}</div>`:'';return `<td>${Number.isFinite(e)?fmt(e)+(r.status!=='OK'?`<div class="muted">${esc(r.status)} +10 %</div>`:'')+pen:esc(r.status==='OK'?'Bez času':r.status)}</td>`}).join('')}<td class="total">${x.eligible?fmt(x.total):'—'}${reg.races.length&&!x.eligible?`<div class="muted">Dokončené ${x.completed}/${reg.races.length}</div>`:''}</td><td class="time-gap">${fmtGap(x.gapPrevious)}</td><td class="time-gap">${fmtGap(x.gapLeader)}</td></tr>`).join('')||'<tr><td colspan="${reg.races.length+5}">Najprv pridajte posádky.</td></tr>'}</tbody></table></div>`}
function pointsWindow(){const st=standings(reg);modal(`<div class="row"><div><div class="eyebrow">PARALELNÉ PORADIE</div><h2>Bodové hodnotenie</h2></div>${button('Zavrieť','close')}</div><p>Low Point · ${reg.discards} zahodení od ${reg.discardAfter}. dokončenej etapy. Zahodenia platia iba pre body.</p><div class="scroll"><table><thead><tr><th>Por.</th><th>Loď</th>${reg.races.map((_,i)=>`<th>E${i+1}</th>`).join('')}<th>Body</th></tr></thead><tbody>${st.map(x=>`<tr><td>${reg.races.length?x.rank+'.':'—'}</td><td><b>${esc(x.crew.boatName)}</b><div class="muted">${esc(x.crew.skipper)}</div></td>${x.scores.map((r,i)=>`<td class="${x.discard.includes(i)?'discard':''}">${r.points}${r.status==='OK'?'':' '+esc(r.status)}</td>`).join('')}<td class="total">${reg.races.length?x.net:'—'}</td></tr>`).join('')||'<tr><td colspan="3">Žiadne posádky.</td></tr>'}</tbody></table></div><p class="muted">Prečiarknuté body sú zahodené. DNE sa nezahadzuje. Rovnosti: A8.1, potom A8.2.</p>`);$('#dialog').classList.add('wide')}
function detail(){const ts=timeStandings(reg),leader=ts.find(x=>x.eligible);return `<div class="breadcrumb">${button('← Regaty','home')}<span> / ${esc(reg.name)}</span></div><div class="eyebrow" style="margin-top:24px">REGATA · ${esc(reg.boatClass||'OPEN')}</div><div class="regatta-heading">${logoMarkup(reg)}<div><h1>${esc(reg.name)}</h1><p>${esc(reg.location)}</p></div></div><div class="grid"><div class="stat"><b>${reg.crews.length}</b><span>Registrovaných lodí</span></div><div class="stat"><b>${reg.races.length} / ${reg.plannedRaces}</b><span>Dokončených etáp</span></div><div class="stat"><b>${leader?esc(leader.crew.boatName):'—'}</b><span>Líder podľa celkového času</span></div></div><nav class="regatta-menu" aria-label="Ovládanie regaty">${button('▶ Nová etapa','race','primary')}${button('Posádky','crews')}${button('Nastavenie regaty','editreg')}${button('Logo regaty','logo')}${button('Živý odpočet / posádky','live')}${button('Excel .xlsx','xlsx')}${button('Záloha JSON','json')}</nav><div class="card"><div class="row"><div><div class="eyebrow">ČASOVÉ HODNOTENIE</div><h2>Každá rozjazda sa počíta.</h2></div><span class="tag">Bez škrtania</span></div>${timeTable()}<p class="muted">Poradie určuje súčet výsledných časov všetkých etáp (čistý čas + tresty podľa sporového protokolu). DNF/DNS/DNC = čas poslednej lode v etape +10 %. Rozdiely sa počítajú z celkového času oproti predchádzajúcej lodi a oproti lídrovi.</p></div><div class="card scoring-launch"><div><div class="eyebrow">SAMOSTATNÉ HODNOTENIE</div><h2>Bodové poradie regaty</h2><p>Paralelné výsledky podľa bodov s nastavenými zahodeniami.</p></div>${button('Otvoriť bodové okno ↗','points','primary')}</div><div class="card"><h2>Etapy</h2>${reg.races.map((r,i)=>`<div class="item row"><div><b>Etapa ${i+1}</b><p>${new Date(r.date).toLocaleString('sk-SK')} · ${r.results.filter(x=>x.status==='OK').length} lodí v cieli</p></div>${button('Výsledky / upraviť','editrace:'+r.id)}</div>`).join('')||'<p>Zatiaľ žiadna dokončená etapa.</p>'}</div>`}
function timerView(){const a=data.active;return `${button('← Regata (meranie pokračuje)','detail')}<div class="card timer"><div class="phase" id="phase"></div><div class="clock countdown-clock" id="clock">05:00</div><button class="clock-expand" data-action="focus">⤢ Veľký odpočet</button><p id="signal"></p><div id="countdown-controls"><div id="duration-control"><div class="mode-switch" role="tablist"><button type="button" class="${a.mode==='time'?'active':''}" data-action="mode:time">Podľa času štartu</button><button type="button" class="${a.mode!=='time'?'active':''}" data-action="mode:manual">Manuálne</button></div>${a.mode==='time'?`<label>Presný čas štartu (podľa hodín)<input id="start-at" type="time" step="60" value="${a.startAt?new Date(a.startAt).toLocaleTimeString('sk-SK',{hour:'2-digit',minute:'2-digit'}):''}"></label><label>Dĺžka štartovej procedúry (1–60 minút)<input id="countdown-minutes" type="number" min="1" max="60" step="1" value="${Math.round((a.remaining??300000)/60000)}"></label><p class="muted">Po spustení beží čakanie do začiatku štartovej procedúry (dopočítané automaticky) a procedúra sa spustí sama tak, aby štart bol presne v zadanom čase.</p>`:`<label>Čakanie do začiatku štartovej procedúry (0–180 minút, 0 = bez čakania)<input id="prestart-minutes" type="number" min="0" max="180" step="1" value="${Math.round((a.preRemaining??0)/60000)}"></label><label>Dĺžka štartovej procedúry (1–60 minút)<input id="countdown-minutes" type="number" min="1" max="60" step="1" value="${Math.round((a.remaining??300000)/60000)}"></label><p class="muted">Po spustení beží čakanie a po jeho uplynutí sa štartová procedúra spustí sama. Hodnoty sa použijú hneď po zadaní.</p>`}</div><div class="sync">${[-5,-1,1,5].map(s=>button((s>0?'+':'')+s+' s','adjust:'+s)).join('')}</div><div class="actions" style="justify-content:center">${button(['PAUSED','PREPAUSED'].includes(a.state)?'▶ Pokračovať':a.state==='READY'?'▶ Spustiť odpočet':'Ⅱ Pauza','toggle','primary')}${['PRESTART','PREPAUSED'].includes(a.state)?button('Začať štartovú procedúru teraz','skipprestart'):''}${button('Okamžitý štart','force')}</div></div><div id="finish-controls"><button class="finish" data-action="finish">🏁 CIEĽ<small id="finish-count"></small></button><p>Každé stlačenie zaznamená jeden dojazd. Po dojazde poslednej lode sa meranie samo zastaví.</p><div class="actions">${button('Vrátiť posledný dojazd','undo')}${button('Ukončiť a vyhodnotiť','evaluate','primary')}</div></div>${button('Zrušiť etapu','abort','danger')}<p class="muted" id="wake-status">Počas merania nechajte aplikáciu otvorenú.</p></div><div class="card"><h2>Zaznamenané dojazdy</h2><div id="finishes"></div></div>`}
function evaluation(){const a=editing||data.active;return `<div class="eyebrow">VYHODNOTENIE</div><h1>${editing?'Upraviť výsledky':'Priradiť dojazdy'}</h1><p>Každému času vyberte loď. Ostatným lodiam určite DNS, DNF alebo iný status. Tresty sa počítajú z času dojazdu poslednej lode v etape, percentá sa sčítavajú a zaokrúhľujú na celé sekundy nahor; DNF/DNS dostane čas poslednej lode +10 %.</p><form id="evaluation"><div class="card">${a.finishes.map((f,i)=>`<div class="item"><div class="row"><b>Dojazd #${i+1} · ${f.ms==null?'bez nameraného času':fmt(f.ms)}</b>${button('Odstrániť','deletefinish:'+i,'danger')}</div><div class="assign"><label>Loď<select name="crew${i}" required><option value="">Vyberte posádku</option>${reg.crews.map(c=>`<option value="${c.id}" ${f.crewId===c.id?'selected':''}>${esc(c.boatName)}</option>`).join('')}</select></label><label>Status<select name="status${i}">${statuses(f.status||'OK')}</select></label><label>Poradie (rovnaké = remíza)<input name="place${i}" type="number" min="1" max="${reg.crews.length}" step="1" value="${f.place||i+1}" required></label><label>Body RDG / DPI / SCP / ZFP<input name="points${i}" type="number" min="0" step="0.1" value="${f.manualPoints??''}"></label></div><details class="penalties" ${(f.penalties||[]).some(p=>p.count>0)?'open':''}><summary>Tresty podľa sporového protokolu${penaltyPct(f)?` · +${penaltyPct(f)} %`:''}</summary><div class="penalty-grid">${PENALTY_TYPES.map(t=>`<label>${t.label}<span class="muted"> ${t.pct?'+'+t.pct+' % času poslednej lode':'bez časového trestu'}</span><input name="pen${i}-${t.code}" type="number" min="0" max="9" step="1" value="${(f.penalties||[]).find(p=>p.code===t.code)?.count||0}"></label>`).join('')}</div><label>Poznámka k trestu<input name="pennote${i}" maxlength="200" value="${esc(f.penaltyNote??'')}"></label></details></div>`).join('')||'<p>Žiadne namerané dojazdy. Určite statusy lodí nižšie.</p>'}</div><div class="card"><h2>Ostatné lode</h2><p class="muted">Tieto statusy sa použijú len pre lode nepriradené k dojazdu.</p>${reg.crews.map(c=>`<label>${esc(c.boatName)}<select name="absent-${c.id}">${statuses(a.absent?.[c.id]||'DNF',false)}</select></label>`).join('')}</div><div class="actions"><button class="success" type="submit">Uložiť výsledky</button>${button(editing?'Zrušiť úpravy':'Späť k meraniu',editing?'canceledit':'backtimer')}</div></form>`}
function statuses(selected,ok=true){return (ok?['OK','DNF','DNS','DNC','OCS','NSC','RET','DSQ','UFD','BFD','DNE','RDG','DPI','SCP','ZFP']:['DNF','DNS','DNC','OCS','NSC','RET','DSQ','UFD','BFD','DNE']).map(s=>`<option ${s===selected?'selected':''}>${s}</option>`).join('')}
function render(){ $('#main').innerHTML=view==='home'?home():view==='detail'?detail():view==='timer'?timerView():evaluation();if(view==='timer')tick(false);if(view==='evaluation')$('#evaluation').onsubmit=saveEvaluation; }
function ask(message,okLabel='Odstrániť'){return new Promise(resolve=>{const d=$('#dialog');d.classList.remove('wide');d.innerHTML=`<h2>Potvrdenie</h2><p>${esc(message)}</p><div class="actions"><button id="ask-ok" class="danger">${esc(okLabel)}</button><button id="ask-cancel">Zrušiť</button></div>`;if(!d.open)d.showModal();const done=v=>{d.oncancel=null;d.close();resolve(v)};$('#ask-ok').onclick=()=>done(true);$('#ask-cancel').onclick=()=>done(false);d.oncancel=e=>{e.preventDefault();done(false)}})}
function modal(html){const d=$('#dialog');if(d.open)d.close();d.classList.remove('wide');d.innerHTML=html;d.showModal()}
function regForm(existing=false){const r=existing?reg:{};modal(`<h2>${existing?'Nastavenie regaty':'Nová regata'}</h2><form id="regform"><label>Názov<input name="name" required maxlength="120" value="${esc(r.name)}"></label><label>Miesto<input name="location" value="${esc(r.location)}"></label><label>Trieda lodí<input name="boatClass" value="${esc(r.boatClass)}"></label><label>Plánované etapy<input name="plannedRaces" type="number" min="1" max="100" value="${r.plannedRaces??6}" required></label><label>Počet zahodení<input name="discards" type="number" min="0" max="99" value="${r.discards??1}" required></label><label>Zahadzovať od počtu dokončených etáp<input name="discardAfter" type="number" min="1" max="100" value="${r.discardAfter??4}" required></label><p class="muted">Nastavte podľa rozpisu regaty a plachetných smerníc. Základné bodovanie A5.2; A5.3 a handicap sa nepoužívajú.</p><div class="actions"><button type="submit" class="primary">Uložiť</button>${button('Zrušiť','close')}</div></form>`);$('#regform').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));for(const k of ['plannedRaces','discards','discardAfter'])f[k]=Number(f[k]);if(f.discards>=f.discardAfter)return toast('Počet zahodení musí byť menší než prah etáp.');if(existing)Object.assign(reg,f);else{reg={...f,id:uid(),crews:[],races:[]};data.regattas.push(reg)}if(persist()){view='detail';$('#dialog').close();render()}}}
function crews(){modal(`<h2>Posádky / lode</h2><form id="crewform"><label>Názov lode<input name="boatName" required maxlength="100"></label><label>Skipper<input name="skipper" maxlength="100"></label><label>Klub<input name="club" maxlength="100"></label><button class="primary" type="submit">+ Pridať loď</button></form>${reg.crews.map(c=>`<div class="item row"><div><b>${esc(c.boatName)}</b><p>${[c.skipper,c.club].filter(Boolean).map(esc).join(' · ')}</p></div><div class="actions">${button('Upraviť názov','renamecrew:'+c.id)}${button('Odstrániť','removecrew:'+c.id,'danger')}</div></div>`).join('')}<div class="actions">${button('Hotovo','close')}</div>`);$('#crewform').onsubmit=e=>{e.preventDefault();if(data.active?.regattaId===reg.id)return toast('Počas rozbehnutej etapy sa zoznam lodí nemení.');const c=Object.fromEntries(new FormData(e.target));for(const k in c)c[k]=c[k].trim();if(!c.boatName)return toast('Vyplňte názov lode.');if(reg.crews.some(x=>x.boatName.toLowerCase()===c.boatName.toLowerCase()))return toast('Loď s týmto názvom už existuje.');reg.crews.push({sailNumber:'',...c,id:uid()});reg.races.forEach(r=>{r.results.push({crewId:reg.crews.at(-1).id,status:'DNC',place:null,ms:null});scoreRace(reg,r.results)});persist();crews();render()}}
function settings(){modal(`<h2>Nastavenia na vode</h2><form id="settingsform"><label>Režim zobrazenia<select name="sun"><option value="false">Tmavý námornícky</option><option value="true" ${data.settings.sun?'selected':''}>Svetlý na slnko</option></select></label><label>Jazyk hlasu<select name="lang"><option value="sk-SK">Slovenčina</option><option value="en-US" ${data.settings.lang==='en-US'?'selected':''}>English</option></select></label><label>Hlasové hlásenia<select name="voice"><option value="true">Zapnuté</option><option value="false" ${!data.settings.voice?'selected':''}>Vypnuté</option></select></label><label>Zvukové signály<select name="sound"><option value="true">Zapnuté</option><option value="false" ${!data.settings.sound?'selected':''}>Vypnuté</option></select></label><label>Štandardná dĺžka odpočtu (1–60 minút)<input name="countdownMinutes" type="number" min="1" max="60" step="1" value="${data.settings.countdownMinutes??5}" required></label><p class="muted">Hlas od 10:00 každú minútu až po 1:00. Posledná minúta: hlásenie 1:00 a záverečný odpočet.</p><label>Záverečné hlasové odpočítavanie (sekundy)<input name="count" type="number" min="0" max="30" value="${data.settings.count}" required></label><p class="muted">Signály 5–4–1–0 minút. Na iPhone sa hlas a signály pri zamknutí alebo prepnutí aplikácie nemusia prehrávať; meranie sa po návrate obnoví.</p><div class="actions">${button('Test zvuku','test')}<button class="primary" type="submit">Uložiť</button>${button('Zavrieť','close')}</div></form>`);$('#settingsform').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));data.settings={lang:f.lang,voice:f.voice==='true',sound:f.sound==='true',sun:f.sun==='true',count:Number(f.count),countdownMinutes:Number(f.countdownMinutes)};document.body.classList.toggle('sun',data.settings.sun);persist();$('#dialog').close()}}
function unlock(){primeSpeech();try{const fresh=!audio;audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume().catch(()=>{});if(fresh)scheduleCues()}catch(e){}}
function beep(long=false){if(!data.settings.sound||!audio)return;try{let o=audio.createOscillator(),g=audio.createGain();o.type='square';o.frequency.value=long?1100:800;g.gain.setValueAtTime(1,audio.currentTime);g.gain.exponentialRampToValueAtTime(.0001,audio.currentTime+(long?.7:.15));o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+(long?.7:.15))}catch(e){}}
let speechPrimed=false;function primeSpeech(){if(speechPrimed||!window.speechSynthesis)return;speechPrimed=true;try{const u=new SpeechSynthesisUtterance(' ');u.volume=0;speechSynthesis.speak(u)}catch(e){}}
function speak(s,keep=false){if(!data.settings.voice||!window.speechSynthesis)return;try{const u=new SpeechSynthesisUtterance(s);u.lang=data.settings.lang;u.rate=1.1;u.volume=1;if(!keep&&(speechSynthesis.speaking||speechSynthesis.pending))speechSynthesis.cancel();setTimeout(()=>speechSynthesis.speak(u),keep?0:60)}catch(e){}}
async function keepAwake(){if(document.visibilityState!=='visible'||!['COUNTDOWN','RACING','PRESTART'].includes(data.active?.state))return;try{wake=await navigator.wakeLock?.request('screen');if($('#wake-status'))$('#wake-status').textContent=wake?'Obrazovka zostáva zapnutá počas merania.':'Nechajte aplikáciu otvorenú a obrazovku zapnutú.'}catch(e){}}
const SILENT_WAV='data:audio/wav;base64,';let bgAudio=null,cueNodes=[],cueGen=0,cueAt=0;
function bgKeepAlive(on){try{if(on){if(!bgAudio){bgAudio=new Audio(SILENT_WAV);bgAudio.loop=true;bgAudio.setAttribute('playsinline','');bgAudio.volume=0.01}bgAudio.play().catch(()=>{})}else if(bgAudio){bgAudio.pause()}}catch(e){}}
function cueList(){const a=data.active,list=[];if(!a)return list;const push=(wall,long)=>list.push({wall,long});if(a.state==='PRESTART'){const pre=Math.ceil((a.preDeadline-now())/1000);for(let sec=1;sec<=pre;sec++)if(sec%60>=1&&sec%60<=5)push(a.preDeadline-sec*1000,false);push(a.preDeadline,true)}const dl=a.state==='COUNTDOWN'?a.deadline:a.state==='PRESTART'?a.preDeadline+a.remaining:null;if(dl!=null){const total=a.state==='COUNTDOWN'?Math.ceil((dl-now())/1000):Math.round(a.remaining/1000),count=Math.max(0,data.settings.count??10);for(let sec=1;sec<=total;sec++){if(sec===60||sec===300||sec===240)push(dl-sec*1000,sec===60);else if(sec>30&&sec%60>=1&&sec%60<=5)push(dl-sec*1000,false);else if(sec<=30&&sec>count)push(dl-sec*1000,false)}push(dl,true)}return list}
function scheduleCues(){cueGen++;for(const o of cueNodes){try{o.stop()}catch(e){}}cueNodes=[];cueAt=now();if(!audio||!data.settings.sound)return;const t0=now(),horizon=t0+20*60000;for(const c of cueList()){if(c.wall<t0-200||c.wall>horizon)continue;try{const o=audio.createOscillator(),g=audio.createGain(),at=audio.currentTime+Math.max(0,(c.wall-t0)/1000),d=c.long?.7:.15;o.type='square';o.frequency.value=c.long?1100:800;g.gain.setValueAtTime(1,at);g.gain.exponentialRampToValueAtTime(.0001,at+d);o.connect(g);g.connect(audio.destination);o.start(at);o.stop(at+d);cueNodes.push(o)}catch(e){}}}
function parseStartAt(v){if(!/^\d{2}:\d{2}$/.test(v||''))return null;const [h,m]=v.split(':').map(Number);const d=new Date();d.setHours(h,m,0,0);let t=d.getTime();if(t<=now()+30000)t+=86400000;return t}
function syncStartAt(a){if(!a||a.state!=='READY'||!a.startAt)return;a.preRemaining=Math.max(0,a.startAt-a.remaining-now())}
function allFinished(){const a=data.active;return !!a&&a.state==='RACING'&&reg&&reg.crews.length>0&&a.finishes.length>=reg.crews.length}
function finishAll(){const a=data.active;if(!a||a.state!=='RACING')return;a.state='EVALUATION';a.stoppedAt=now();persist();wake?.release();beep(true);speak(data.settings.lang==='sk-SK'?'Všetky lode v cieli':'All boats finished');toast('Posledná loď v cieli – meranie zastavené.');view='evaluation';render()}
function tick(sound=true){const a=data.active;if(!a)return;const t=now();if(['PRESTART','COUNTDOWN'].includes(a.state)&&t-cueAt>5*60000)scheduleCues();if(a.state==='PRESTART'&&t>=a.preDeadline){a.state='COUNTDOWN';a.deadline=a.preDeadline+a.remaining;a.preRemaining=0;persist();if(sound&&t-a.preDeadline<1500){speak(data.settings.lang==='sk-SK'?'Vypnúť motory. Vypnúť motory. Vypnúť motory.':'Engines off. Engines off. Engines off.',true)}lastSecond=Math.ceil((a.deadline-t)/1000);scheduleCues();if(view==='timer')render();return}if(a.state==='PRESTART'){const sec=Math.ceil((a.preDeadline-t)/1000);if(sec!==lastSecond){if(sound){if(sec===60)speak(data.settings.lang==='sk-SK'?'Minúta do začiatku štartovej procedúry':'One minute to the start sequence')}lastSecond=sec}}if(a.state==='COUNTDOWN'&&t>=a.deadline){a.state='RACING';a.start=a.deadline;persist();bgKeepAlive(false);scheduleCues();if(sound&&t-a.start<1500){speak(data.settings.lang==='sk-SK'?'Štart':'Start')}lastSecond=0;if(view==='timer')render();return}if(a.state==='COUNTDOWN'){const sec=Math.ceil((a.deadline-t)/1000);if(sec!==lastSecond){if(sound){const announcement=countdownAnnouncement(sec,data.settings.count);if(announcement){if(announcement.kind==='minute'){const m=announcement.value;speak(data.settings.lang==='sk-SK'?(m===1?'Minúta do štartu':m<5?`${m} minúty do štartu`:`${m} minút do štartu`):`${m} ${m===1?'minute':'minutes'} to start`)}else speak(String(announcement.value))}}lastSecond=sec}}if(view!=='timer')return;const racing=a.state==='RACING';const pre=['PRESTART','PREPAUSED'].includes(a.state);const phaseText=racing?'PRETEKY PREBIEHAJÚ':a.state==='PAUSED'?'ODPOČET POZASTAVENÝ':a.state==='PRESTART'||(a.state==='READY'&&(a.preRemaining||0)>0)?'PRÍPRAVA NA ŠTARTOVÚ PROCEDÚRU':a.state==='PREPAUSED'?'PRÍPRAVA POZASTAVENÁ':'ŠTART';$('#phase').textContent=phaseText;$('#phase').classList.toggle('big',phaseText.length<=8);const readyWait=a.state==='READY'&&(a.preRemaining||0)>0;let sec=a.state==='COUNTDOWN'?Math.ceil((a.deadline-t)/1000):a.state==='PRESTART'?Math.ceil((a.preDeadline-t)/1000):a.state==='PREPAUSED'?Math.ceil((a.preRemaining||0)/1000):readyWait?Math.ceil(a.preRemaining/1000):Math.ceil((a.remaining??300000)/1000);$('#clock').classList.toggle('countdown-clock',!racing);$('#clock').classList.toggle('racing-clock',racing);$('#clock').textContent=racing?fmt(t-a.start):`${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`;$('#clock').classList.toggle('final',!racing&&sec<=10);const nextMinute=Math.min(600,Math.floor((sec-1)/60)*60);$('#signal').textContent=racing?'ČAS OD ŠTARTU':pre?`Potom automaticky začne štartový odpočet ${Math.round(a.remaining/60000)} min.${a.state==='PRESTART'?` Štart o ${new Date(a.preDeadline+a.remaining).toLocaleTimeString('sk-SK',{hour:'2-digit',minute:'2-digit'})}.`:''}`:a.state==='READY'&&a.mode==='time'&&!a.startAt?'Zadajte presný čas štartu.':readyWait?`1. čakanie ${Math.round(a.preRemaining/60000)} min → 2. štartový odpočet ${Math.round(a.remaining/60000)} min → štart${a.startAt?' o '+new Date(a.startAt).toLocaleTimeString('sk-SK',{hour:'2-digit',minute:'2-digit'}):''}`:sec>60?`Ďalšie hlasové hlásenie: ${Math.floor(nextMinute/60)}:00`:'Posledná minúta · záverečný odpočet';$('#duration-control').hidden=a.state!=='READY';const dc=$('#duration-control');if(a.state==='READY')syncStartAt(a);if(a.state==='READY'&&dc?.dataset&&!dc.dataset.bound){dc.dataset.bound='1';for(const id of ['#countdown-minutes','#prestart-minutes'])$(id)?.addEventListener?.('change',()=>actions.duration());$('#start-at')?.addEventListener?.('change',()=>actions.startat())}$('#countdown-controls').hidden=racing;$('#finish-controls').hidden=!racing;$('#finish-count').textContent=`Dojazdy: ${a.finishes.length} / ${reg.crews.length}`;$('#finishes').innerHTML=a.finishes.map((f,i)=>`<div class="item row raw"><span>#${i+1}</span><span>${f.ms==null?'bez nameraného času':fmt(f.ms)}</span><span class="muted">${esc(reg.crews.find(c=>c.id===f.crewId)?.boatName||'')}${f.recordedBy?` <small>· zapísala ${esc(f.recordedBy)}</small>`:''}</span><span class="tag">CIEĽ</span></div>`).reverse().join('')||'<p>Zatiaľ žiadny dojazd.</p>'}
function captureForm(){const a=editing||data.active;if(!$('#evaluation'))return;const f=new FormData($('#evaluation'));a.finishes.forEach((x,i)=>{x.crewId=f.get('crew'+i);x.status=f.get('status'+i);x.place=Number(f.get('place'+i));x.manualPoints=f.get('points'+i)===''?null:Number(f.get('points'+i));x.penalties=PENALTY_TYPES.map(t=>({code:t.code,count:Number(f.get(`pen${i}-${t.code}`))||0})).filter(p=>p.count>0);x.penaltyNote=(f.get('pennote'+i)||'').trim()});a.absent=Object.fromEntries(reg.crews.map(c=>[c.id,f.get('absent-'+c.id)]));if(!editing)persist()}
function saveEvaluation(e){e.preventDefault();captureForm();const a=editing||data.active,ids=a.finishes.map(x=>x.crewId);if(ids.some(x=>!x)||new Set(ids).size!==ids.length)return toast('Priraďte každý dojazd inej lodi.');if(a.finishes.some(x=>['RDG','DPI','SCP','ZFP'].includes(x.status)&&x.manualPoints==null))return toast('Pri osobitnom statuse zadajte body rozhodnuté komisiou.');const results=a.finishes.map(x=>({...x}));reg.crews.filter(c=>!ids.includes(c.id)).forEach(c=>results.push({crewId:c.id,status:a.absent[c.id],place:null,ms:null}));scoreRace(reg,results);applyPenalties(results);if(editing){const r=reg.races.find(x=>x.id===editing.id);r.results=results;r.updatedAt=new Date().toISOString()}else reg.races.push({id:uid(),date:new Date().toISOString(),start:a.start,results});data.active=editing?data.active:null;editing=null;if(persist()){wake?.release();view='detail';render();toast('Výsledky uložené.')}}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}
function importJSON(){let input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{let x=JSON.parse(await input.files[0].text()),list=x.regattas||[x];if(!Array.isArray(list)||list.length>100)throw Error();const cleaned=list.map(r=>{if(typeof r.name!=='string'||!Array.isArray(r.crews)||!Array.isArray(r.races)||r.crews.length>500||r.races.length>100)throw Error();if(r.logo!=null&&!validLogo(r.logo))throw Error();const ids=new Set(r.crews.map(c=>c.id));if(ids.size!==r.crews.length||r.crews.some(c=>typeof c.id!=='string'||typeof c.boatName!=='string'))throw Error();const plannedRaces=Number(r.plannedRaces??6),discards=Number(r.discards??1),discardAfter=Number(r.discardAfter??Math.max(4,discards+1));if(![plannedRaces,discards,discardAfter].every(Number.isInteger)||plannedRaces<1||discards<0||discardAfter<=discards)throw Error();return {...r,live:undefined,id:uid(),plannedRaces,discards,discardAfter,races:r.races.map(q=>{if(!Array.isArray(q.results)||!Number.isFinite(Date.parse(q.date)))throw Error();const seen=new Set();const results=q.results.filter(y=>y.crewId).map(y=>{if(!ids.has(y.crewId)||seen.has(y.crewId))throw Error();seen.add(y.crewId);const status=y.status;if(!['OK','DNF','DNS','DNC','OCS','NSC','RET','DSQ','UFD','BFD','DNE','RDG','DPI','SCP','ZFP'].includes(status))throw Error();const place=Number(y.place??y.finishPosition),ms=y.ms??y.timeMs??null,manualPoints=y.manualPoints??y.points;if(status==='OK'&&(!Number.isInteger(place)||place<1))throw Error();if(ms!==null&&(!Number.isFinite(ms)||ms<0))throw Error();if(['RDG','DPI','SCP','ZFP'].includes(status)&&(!Number.isFinite(manualPoints)||manualPoints<0))throw Error();return {crewId:y.crewId,status,place,ms,manualPoints}});return {...q,id:uid(),results:scoreRace(r,results)}})}});data.regattas.push(...cleaned);persist();view='home';render();toast('Záloha importovaná ako nové regaty.')}catch(e){toast('Neplatná alebo nepodporovaná záloha JSON.')}};input.click()}
const actions={logo:logoManager,points:pointsWindow,duration(){const n=Number($('#countdown-minutes').value),pEl=$('#prestart-minutes'),p=pEl?Number(pEl.value):Math.round((data.active.preRemaining||0)/60000);if(!Number.isInteger(n)||n<1||n>60)return toast('Zadajte celé minúty od 1 do 60.');if(!Number.isInteger(p)||p<0||p>180)return toast('Čakanie zadajte v celých minútach od 0 do 180.');if(data.active.state!=='READY')return;data.active.remaining=n*60000;data.settings.countdownMinutes=n;if(data.active.startAt){syncStartAt(data.active)}else{data.active.preRemaining=p*60000;data.settings.prestartMinutes=p}persist();tick(false);toast(data.active.startAt?`Štart o ${new Date(data.active.startAt).toLocaleTimeString('sk-SK',{hour:'2-digit',minute:'2-digit'})}: čakanie ${Math.round(data.active.preRemaining/60000)} min, odpočet ${n} min.`:p>0?`Čakanie ${p} min, potom odpočet ${n} min.`:'Odpočet nastavený na '+n+' min.');},home(){view='home';render()},detail(){view='detail';render()},new(){regForm()},editreg(){regForm(true)},crews,close(){$('#dialog').close()},restore(){reg=data.regattas.find(r=>r.id===data.active.regattaId);view=data.active.state==='EVALUATION'?'evaluation':'timer';render();scheduleCues();keepAwake()},race(){if(data.active)return toast('Najprv dokončite alebo zrušte rozbehnutú etapu.');if(!reg.crews.length)return crews();data.active={id:uid(),regattaId:reg.id,state:'READY',remaining:(data.settings.countdownMinutes??5)*60000,preRemaining:(data.settings.prestartMinutes??0)*60000,mode:data.settings.startMode||'manual',finishes:[]};persist();view='timer';lastSecond=null;render()},toggle(){let a=data.active;if(a.state==='COUNTDOWN'){a.remaining=Math.max(0,a.deadline-now());a.state='PAUSED';wake?.release()}else if(a.state==='PRESTART'){a.preRemaining=Math.max(0,a.preDeadline-now());a.state='PREPAUSED';wake?.release()}else if(a.state==='READY'&&a.mode==='time'&&!a.startAt){return toast('Zadajte presný čas štartu alebo prepnite na Manuálne.')}else if(a.state==='READY'&&a.startAt){if(a.startAt-a.remaining<=now()){a.startAt=null;toast('Čas štartu už uplynul – spúšťam odpočet hneď.');a.deadline=now()+a.remaining;a.state='COUNTDOWN'}else{a.preDeadline=a.startAt-a.remaining;a.preRemaining=a.preDeadline-now();a.state='PRESTART'}lastSecond=null;keepAwake()}else if(a.state==='PREPAUSED'||(a.state==='READY'&&(a.preRemaining||0)>0)){a.preDeadline=now()+a.preRemaining;a.state='PRESTART';lastSecond=null;keepAwake()}else if(['READY','PAUSED'].includes(a.state)){a.deadline=now()+a.remaining;a.state='COUNTDOWN';lastSecond=null;keepAwake()}persist();bgKeepAlive(['PRESTART','COUNTDOWN'].includes(a.state));scheduleCues();render();lastSecond=null;},startat(){const a=data.active;if(!a||a.state!=='READY')return;const v=$('#start-at').value;if(!v){a.startAt=null;a.preRemaining=0;persist();tick(false);return}const startAt=parseStartAt(v);if(!startAt)return toast('Zadajte čas štartu (hh:mm).');const total=startAt-now();if(total>12*3600000){$('#start-at').value='';return toast('Čas štartu je príliš ďaleko (max. 12 hodín).')}if(total<=a.remaining+5000){$('#start-at').value='';return toast('Do štartu zostáva menej než dĺžka štartového odpočtu ('+Math.round(a.remaining/60000)+' min). Zvoľte neskorší čas.')}a.startAt=startAt;syncStartAt(a);persist();render();toast('Štart o '+v+' – čakanie '+Math.round(a.preRemaining/60000)+' min, potom odpočet '+Math.round(a.remaining/60000)+' min.')},skipprestart(){const a=data.active;if(!['PRESTART','PREPAUSED'].includes(a.state))return;a.preRemaining=0;a.deadline=now()+a.remaining;a.state='COUNTDOWN';lastSecond=null;beep(true);persist();scheduleCues();keepAwake();render()},force(){const a=data.active;if(!['READY','COUNTDOWN','PAUSED','PRESTART','PREPAUSED'].includes(a.state))return;a.start=now();a.state='RACING';bgKeepAlive(false);scheduleCues();beep(true);speak(data.settings.lang==='sk-SK'?'Štart':'Start');persist();keepAwake();render()},finish(){const a=data.active;if(a?.state!=='RACING')return;a.finishes.push({id:uid(),ms:Math.max(0,now()-a.start),status:'OK'});persist();beep();if(navigator.vibrate)navigator.vibrate(35);if(allFinished()){finishAll();return}tick(false)},async undo(){if(!data.active.finishes.length)return;if(await ask('Odstrániť posledný dojazd?')){data.active.finishes.pop();persist();tick(false)}},async abort(){if(await ask('Zrušiť etapu a odstrániť namerané dojazdy?','Zrušiť etapu')){data.active=null;persist();bgKeepAlive(false);scheduleCues();wake?.release();view='detail';render()}},evaluate(){if(data.active.state!=='RACING')return;data.active.state='EVALUATION';persist();wake?.release();view='evaluation';render()},backtimer(){captureForm();data.active.state='RACING';persist();view='timer';render();keepAwake()},canceledit(){editing=null;view='detail';render()},json(){const {live,...backup}=reg;download(new Blob([JSON.stringify(backup,null,2)],{type:'application/json'}),'regatta-zaloha.json')},xlsx(){exportExcel(reg)},import:importJSON,test(){beep(true);speak(data.settings.lang==='sk-SK'?'Časomiera je pripravená':'Timer ready')},demo(){reg={id:uid(),name:'Dunajský pohár · ukážka',location:'Bratislava',boatClass:'Open',plannedRaces:6,discards:1,discardAfter:4,crews:[{id:uid(),sailNumber:'SVK 01',boatName:'Wind Star',skipper:'Ján Novák',club:'YC Bratislava'},{id:uid(),sailNumber:'SVK 22',boatName:'Blue Wave',skipper:'Eva Kováčová',club:'YC Dunaj'},{id:uid(),sailNumber:'SVK 37',boatName:'Aurora',skipper:'Martin Bielik',club:'YC Senec'}],races:[]};for(let i=0;i<3;i++)reg.races.push({id:uid(),date:new Date().toISOString(),results:scoreRace(reg,reg.crews.map((c,k)=>({crewId:c.id,status:'OK',place:(k+i)%3+1,ms:((k+i)%3+1)*45000+900000})))});data.regattas.push(reg);persist();view='detail';render()}};
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;e.preventDefault();unlock();const [action,id]=b.dataset.action.split(':');if(actions[action])return actions[action]();if(action==='open'){reg=data.regattas.find(x=>x.id===id);view='detail';render()}if(action==='mode'){const a=data.active;if(a&&a.state==='READY'){a.mode=id;data.settings.startMode=id;if(id==='manual'){a.startAt=null;a.preRemaining=(data.settings.prestartMinutes??0)*60000}persist();render()}}if(action==='adjust'){const a=data.active;if(a.state==='COUNTDOWN')a.deadline=Math.min(now()+3600000,a.deadline+Number(id)*1000);else if(a.state==='PRESTART')a.preDeadline=Math.min(now()+10800000,a.preDeadline+Number(id)*1000);else if(a.state==='PREPAUSED')a.preRemaining=Math.min(10800000,Math.max(0,a.preRemaining+Number(id)*1000));else if(['READY','PAUSED'].includes(a.state))a.remaining=Math.min(3600000,Math.max(0,a.remaining+Number(id)*1000));persist();scheduleCues();tick(false)}if(action==='renamecrew')renameCrew(id);if(action==='removecrew'){if(data.active?.regattaId===reg.id)return toast('Počas rozbehnutej etapy nemožno odstrániť loď. Najprv etapu dokončite alebo zrušte.');const name=reg.crews.find(c=>c.id===id)?.boatName||'';const hasResults=reg.races.some(r=>r.results.some(x=>x.crewId===id));ask(hasResults?`Odstrániť loď ${name} aj s jej výsledkami vo všetkých etapách? Poradie ostatných lodí sa prepočíta.`:`Odstrániť loď ${name}?`).then(ok=>{if(ok){reg.crews=reg.crews.filter(c=>c.id!==id);for(const r of reg.races){r.results=r.results.filter(x=>x.crewId!==id);scoreRace(reg,r.results);applyPenalties(r.results)}persist();crews();render();toast('Loď '+name+' odstránená.')}else crews()})}if(action==='editrace'){if(data.active?.regattaId===reg.id)return toast('Najprv dokončite rozbehnutú etapu.');const r=reg.races.find(x=>x.id===id);editing={id:r.id,finishes:r.results.map(x=>({...x})),absent:Object.fromEntries(r.results.filter(x=>x.ms==null).map(x=>[x.crewId,x.status]))};view='evaluation';render()}if(action==='deletefinish'){captureForm();ask('Odstrániť tento dojazd?').then(ok=>{if(ok){(editing||data.active).finishes.splice(Number(id),1);if(!editing)persist();render()}})}});
$('#settings').onclick=()=>{unlock();settings()};$('.brand').onclick=e=>{e.preventDefault();view='home';render()};document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'){anchorWall=Date.now();anchorMono=performance.now();lastSecond=null;scheduleCues();tick(false);keepAwake()}});document.addEventListener('change',e=>{if(view==='evaluation'&&e.target.closest('#evaluation'))captureForm()});window.addEventListener('beforeunload',()=>persist());setInterval(tick,50);load();if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});

function renameCrew(id){const crew=reg.crews.find(c=>c.id===id);if(!crew)return;modal(`<h2>Upraviť názov lode</h2><p>${esc(crew.skipper)}</p><form id="rename-form"><label>Názov lode<input name="boatName" value="${esc(crew.boatName)}" maxlength="100" required></label><div class="actions"><button type="submit" class="primary">Uložiť názov</button>${button('Zrušiť','crews')}</div></form>`);$('#rename-form').onsubmit=e=>{e.preventDefault();const name=new FormData(e.target).get('boatName').trim();if(!name)return toast('Zadajte názov lode.');crew.boatName=name;if(persist()){crews();render();toast('Názov lode uložený.')}}}
function logoMarkup(r,cls='regatta-logo'){return validLogo(r.logo)?`<img class="${cls}" src="${esc(r.logo)}" alt="Logo regaty ${esc(r.name)}">`:''}
async function prepareLogo(file){if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('Vyberte obrázok PNG, JPG alebo WebP.');if(file.size>8*1024*1024)throw Error('Obrázok môže mať najviac 8 MB.');const source=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Obrázok sa nepodarilo načítať.'));reader.readAsDataURL(file)});const img=await new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=()=>reject(Error('Súbor sa nepodarilo otvoriť ako obrázok.'));i.src=source});if(!img.naturalWidth||!img.naturalHeight||img.naturalWidth*img.naturalHeight>40000000)throw Error('Obrázok je príliš veľký. Použite menšie logo.');const canvas=document.createElement('canvas'),scale=Math.min(1,512/Math.max(img.naturalWidth,img.naturalHeight));canvas.width=Math.max(1,Math.round(img.naturalWidth*scale));canvas.height=Math.max(1,Math.round(img.naturalHeight*scale));const ctx=canvas.getContext('2d');if(!ctx)throw Error('Spracovanie obrázka nie je dostupné.');ctx.drawImage(img,0,0,canvas.width,canvas.height);const result=canvas.toDataURL('image/webp',.9);if(!validLogo(result))throw Error('Logo je príliš veľké na uloženie. Vyberte jednoduchší obrázok.');return result}
function logoManager(){let pending=validLogo(reg.logo)?reg.logo:null,sequence=0;const target=reg;modal(`<h2>Logo regaty</h2><p>${esc(reg.name)}</p><div id="logo-preview" class="logo-preview"></div><label>Vybrať logo<input id="logo-file" type="file" accept="image/png,image/jpeg,image/webp"></label><p class="muted">PNG, JPG alebo WebP, najviac 8 MB. Logo sa automaticky zmenší, zachová pomer strán a priehľadnosť.</p><div id="logo-status" class="muted" role="status"></div><div class="actions"><button id="logo-save" class="primary" type="button">Uložiť logo</button><button id="logo-remove" class="danger" type="button">Odstrániť logo</button>${button('Zrušiť','close')}</div>`);const preview=()=>{$('#logo-preview').innerHTML=pending?logoMarkup({name:target.name,logo:pending},'logo-upload-preview'):'<span>Žiadne logo</span>';$('#logo-remove').disabled=!pending};preview();const fileInput=$('#logo-file');fileInput.onchange=async e=>{const file=e.target.files[0];if(!file)return;const token=++sequence;$('#logo-save').disabled=true;$('#logo-status').textContent='Spracúvam obrázok…';try{const result=await prepareLogo(file);if(token!==sequence||!$('#dialog').open||$('#logo-file')!==fileInput)return;pending=result;preview();$('#logo-status').textContent='Logo je pripravené na uloženie.'}catch(err){if(token===sequence&&$('#dialog').open&&$('#logo-file')===fileInput)$('#logo-status').textContent=err.message}finally{if(token===sequence&&$('#dialog').open&&$('#logo-file')===fileInput)$('#logo-save').disabled=false}};$('#logo-remove').onclick=()=>{sequence++;pending=null;$('#logo-file').value='';$('#logo-save').disabled=false;$('#logo-status').textContent='Odstránenie potvrďte uložením.';preview()};$('#logo-save').onclick=()=>{const previous=target.logo;target.logo=pending;if(persist()){$('#dialog').close();render();toast(pending?'Logo regaty uložené.':'Logo regaty odstránené.')}else target.logo=previous}}
